using Kaff.Domain.Common;

namespace Kaff.Domain.DailyLogs;

/// <summary>
/// Base of everything an engineer records on a daily log. <b>Two times, never one</b> (KAFF-600 rule 11):
/// <see cref="OccurredAt"/> is when it happened on site, in the offset the engineer's device was in, and
/// <see cref="CreatedAt"/> is when the server received it. A log written offline across midnight reaches the
/// server on the next day; only <see cref="OccurredAt"/> can put it back on the right one.
/// </summary>
/// <remarks>
/// The <see cref="Entity.Id"/> is generated by the client, so a sync that is retried after a dropped
/// response is recognised as the same entry and is not counted twice. Entries are never edited.
/// </remarks>
public abstract class LogEntry : Entity
{
    protected LogEntry()
    {
    }

    protected LogEntry(Guid id, DailyLog log, DateTimeOffset occurredAt, DateTimeOffset createdAt)
        : base(id)
    {
        DailyLogId = log.Id;
        ProjectId = log.ProjectId;
        // Stored as the same instant at UTC: the day the entry belongs to was fixed from the offset it arrived
        // with when the log was found, and PostgreSQL's timestamptz keeps instants, not offsets.
        OccurredAt = occurredAt.ToUniversalTime();
        CreatedAt = createdAt;
    }

    public Guid DailyLogId { get; private set; }

    /// <summary>Repeated on the entry so the audit trail files it under its project.</summary>
    public Guid ProjectId { get; private set; }

    public DateTimeOffset OccurredAt { get; private set; }

    public DateTimeOffset CreatedAt { get; private set; }
}

/// <summary>
/// An executed quantity: a period <b>delta</b> against one BOQ line (spec.md section 8). Whether a second
/// entry on the same line replaces or adds is <c>RulingSet.DailyLogQuantityEntry</c>.
/// </summary>
public sealed class ExecutedQuantityEntry : LogEntry
{
    private ExecutedQuantityEntry()
    {
    }

    internal ExecutedQuantityEntry(Guid id, DailyLog log, Guid boqLineId, decimal quantity, DateTimeOffset occurredAt, DateTimeOffset createdAt)
        : base(id, log, occurredAt, createdAt)
    {
        BoqLineId = boqLineId;
        Quantity = quantity;
    }

    public Guid BoqLineId { get; private set; }

    public decimal Quantity { get; private set; }
}

/// <summary>Hours a day labourer (يومية) worked, as the engineer saw it. Carries no rate: the rate is Finance's.</summary>
public sealed class DayLabourEntry : LogEntry
{
    public const decimal MaxHours = 24m;

    private DayLabourEntry()
    {
    }

    internal DayLabourEntry(Guid id, DailyLog log, Guid employeeId, decimal hours, DateTimeOffset occurredAt, DateTimeOffset createdAt)
        : base(id, log, occurredAt, createdAt)
    {
        EmployeeId = employeeId;
        Hours = hours;
    }

    public Guid EmployeeId { get; private set; }

    public decimal Hours { get; private set; }
}

/// <summary>
/// Material recorded on site, by type. A count, never a value: the value of a تشوينات
/// (<c>MaterialAdvance</c>) is Finance's and arrives with the extract.
/// </summary>
public sealed class MaterialEntry : LogEntry
{
    public const int MaxLength = 200;

    private MaterialEntry()
    {
    }

    internal MaterialEntry(
        Guid id, DailyLog log, string materialType, decimal quantity, string unit, bool isStockpile, DateTimeOffset occurredAt, DateTimeOffset createdAt)
        : base(id, log, occurredAt, createdAt)
    {
        MaterialType = materialType;
        Quantity = quantity;
        Unit = unit;
        IsStockpile = isStockpile;
    }

    public string MaterialType { get; private set; } = null!;

    public decimal Quantity { get; private set; }

    public string Unit { get; private set; } = null!;

    /// <summary>True when the material is stock held on site (تشوينات), false when it is simply material used.</summary>
    public bool IsStockpile { get; private set; }
}

/// <summary>
/// A site photo. <see cref="IsPublished"/> starts false and nothing here sets it: photos are published
/// deliberately, never mirrored (spec.md section 8, KAFF-600 rule 8; the publish step is KAFF-606).
/// </summary>
public sealed class PhotoEntry : LogEntry
{
    private PhotoEntry()
    {
    }

    internal PhotoEntry(Guid id, DailyLog log, string fileReference, string? caption, DateTimeOffset occurredAt, DateTimeOffset createdAt)
        : base(id, log, occurredAt, createdAt)
    {
        FileReference = fileReference;
        Caption = caption;
    }

    /// <summary>An opaque key into file storage. The upload transport is not part of this slice.</summary>
    public string FileReference { get; private set; } = null!;

    public string? Caption { get; private set; }

    public bool IsPublished { get; private set; }
}

/// <summary>The single-valued fields of a log, where the latest timestamp wins (spec.md section 8).</summary>
public enum DailyLogField
{
    CheckIn = 1,
    CheckOut = 2,
    Weather = 3,
    Note = 4,
    StoppageReason = 5,
}

/// <summary>Why a check-in or check-out is flagged for a reader. It is a flag, never a refusal (Q-207-3, Q-207-4).</summary>
public enum CheckInFlagReason
{
    /// <summary>The phone gave no usable location: denied, unavailable, timed out or out of range.</summary>
    LocationUnavailable = 1,

    /// <summary>The location is farther from the project's reference point than <c>CheckInDistanceRule</c> allows.</summary>
    FarFromReference = 2,
}

/// <summary>
/// One recording of a single-valued field. The log never overwrites: it keeps every recording and the
/// value in force is the one with the latest <see cref="LogEntry.OccurredAt"/>, so an out-of-order sync
/// resolves to the same answer as an in-order one. For <see cref="DailyLogField.CheckIn"/> and
/// <see cref="DailyLogField.CheckOut"/> the value is the <see cref="LogEntry.OccurredAt"/> itself.
/// </summary>
public sealed class FieldEntry : LogEntry
{
    private FieldEntry()
    {
    }

    internal FieldEntry(
        Guid id,
        DailyLog log,
        DailyLogField field,
        string? text,
        DateTimeOffset occurredAt,
        DateTimeOffset createdAt,
        double? latitude = null,
        double? longitude = null,
        double? accuracyMetres = null,
        CheckInFlagReason? flag = null)
        : base(id, log, occurredAt, createdAt)
    {
        Field = field;
        Text = text;
        Latitude = latitude;
        Longitude = longitude;
        AccuracyMetres = accuracyMetres;
        FlagReason = flag;
    }

    public DailyLogField Field { get; private set; }

    public string? Text { get; private set; }

    // Coordinates are degrees, not money: double is correct here and nothing on this entry is a money value.

    /// <summary>Check-in and check-out only. Null when the phone gave no usable location.</summary>
    public double? Latitude { get; private set; }

    public double? Longitude { get; private set; }

    /// <summary>The phone's reported accuracy radius in metres. Null when not reported.</summary>
    public double? AccuracyMetres { get; private set; }

    /// <summary>Set when a reader should look twice. Null for an unremarkable entry.</summary>
    public CheckInFlagReason? FlagReason { get; private set; }
}

/// <summary>
/// An engineer's site expense, entered as a <b>draft</b> (spec.md section 8, KAFF-600 rules 9 and 10).
/// It is not a posting and cannot become one here: Accounts confirms and posts it, in a later slice.
/// </summary>
public sealed class SiteExpenseDraft : LogEntry
{
    private SiteExpenseDraft()
    {
    }

    internal SiteExpenseDraft(Guid id, DailyLog log, string description, Money amount, DateTimeOffset occurredAt, DateTimeOffset createdAt)
        : base(id, log, occurredAt, createdAt)
    {
        Description = description;
        Amount = amount;
    }

    public string Description { get; private set; } = null!;

    public Money Amount { get; private set; }
}
